/* Service worker: caches the whole app so it works with no internet. Generated by tools/build.py */
const VERSION = '1.1.0';
const CACHE = 'biblioteca-rosas-' + VERSION;
const ASSETS = [
 "./",
 "css/app.css",
 "css/fonts.css",
 "data/book1.js",
 "data/book1b.js",
 "data/book2.js",
 "data/book3.js",
 "data/book4.js",
 "data/book5.js",
 "data/lexicon.js",
 "data/lexicon2.js",
 "data/lexicon3.js",
 "fonts/atkinson-hyperlegible-latin-400-italic.woff2",
 "fonts/atkinson-hyperlegible-latin-400-normal.woff2",
 "fonts/atkinson-hyperlegible-latin-700-italic.woff2",
 "fonts/atkinson-hyperlegible-latin-700-normal.woff2",
 "fonts/cormorant-garamond-latin-600-italic.woff2",
 "fonts/cormorant-garamond-latin-600-normal.woff2",
 "fonts/cormorant-garamond-latin-700-normal.woff2",
 "fonts/dancing-script-latin-600-normal.woff2",
 "fonts/dancing-script-latin-700-normal.woff2",
 "fonts/lora-latin-400-italic.woff2",
 "fonts/lora-latin-400-normal.woff2",
 "fonts/lora-latin-600-italic.woff2",
 "fonts/lora-latin-600-normal.woff2",
 "icons/favicon-32.png",
 "icons/favicon.svg",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/maskable-512.png",
 "index.html",
 "js/core.js",
 "js/covers.js",
 "js/dict.js",
 "js/fx.js",
 "js/main.js",
 "js/quiz.js",
 "js/reader.js",
 "js/screens.js",
 "js/tutor.js",
 "js/vocab.js",
 "manifest.webmanifest"
];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k.startsWith('biblioteca-rosas-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  if (url.pathname.endsWith('/version.json')) {
    e.respondWith(fetch(req).catch(() => new Response('{}', { headers: { 'Content-Type': 'application/json' } })));
    return;
  }
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(res => {
    if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  }).catch(() => req.mode === 'navigate' ? caches.match('./index.html') : Promise.reject('offline'))));
});
